// #ece93f (6a993d6d5fdc2434e9ece93f) AC5 — отметка в записи попытки у Super Admin: «מסלול ביקורת» → «אמירות שסומנו בשיחה»,
// сервер без причины/с неверной причиной не отдаёт отчёт, диалог «צפייה בתוכן» без причины не открывает контент.
// Кейсы FLG-003…FLG-006. Источник истины — ответ get_attempt_audit_trail (attempts[].content_flags). Только чтение.
// Открытие трассы пишет запись в журнал доступа SA (норма, D-25). Админка — только десктоп.
// Диалог «צפייה בתוכן» только открывается и закрывается: без причины контент не открывается и в журнал ничего не пишется.
import { test, expect } from '../../fixtures';
import { openTrail, openSupport, openRowMenu, flagText, clock } from './support-helpers';

const HASH = '#ece93f · #6a993d6d5fdc2434e9ece93f';
const FLAGGED = ['QA-CALL1-0411', 'QA-C10-2110-D3'];
const CLEAN = 'QA-PHONE-17fdd9-0411-C';

test.describe(`Поддержка — отметки контента в «מסלול ביקורת» и доступ к контенту (${HASH})`, () => {
  for (const name of FLAGGED) {
    test(`${name}: в панели «אמירות שסומנו בשיחה» те же отметки, что в API (тип, номер попытки, время) @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const { drawer, trail } = await openTrail(admin, name);
      const expected = trail.attempts.flatMap((a, i) => (a.content_flags ?? []).filter((f) => !!f && typeof f.category === 'string').map((f) => ({ ...f, attempt: i + 1 })));
      expect(expected.length, `у ${name} в API трассы нет content_flags — данные изменились`).toBeGreaterThan(0);

      await expect(drawer.getByRole('heading', { name: 'אמירות שסומנו בשיחה' })).toBeVisible();
      const items = drawer.getByTestId('audit-content-flag');
      await expect(items, 'число отметок = числу в API').toHaveCount(expected.length);
      for (let i = 0; i < expected.length; i++) {
        // Источник: AC5 + ответ 05.11 — экраны показывают тип и время, не слова кандидата.
        await expect(items.nth(i)).toContainText(flagText(expected[i].category));
        await expect(items.nth(i)).toContainText(`ניסיון ${expected[i].attempt}`);
        if (expected[i].offset_ms !== null) await expect(items.nth(i)).toContainText(clock(expected[i].offset_ms!));
      }
    });
  }

  test(`${CLEAN}: без отметок в API — в панели «לא סומנו אמירות פוגעניות בשיחות.», пунктов-отметок нет @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { drawer, trail } = await openTrail(admin, CLEAN);
    const flags = trail.attempts.flatMap((a) => a.content_flags ?? []);
    expect(flags, `у ${CLEAN} в API есть отметки — данные изменились`).toHaveLength(0);
    await expect(drawer.getByRole('heading', { name: 'אמירות שסומנו בשיחה' })).toBeVisible();
    await expect(drawer.getByTestId('audit-content-flag')).toHaveCount(0);
    await expect(drawer.getByText('לא סומנו אמירות פוגעניות בשיחות.')).toBeVisible();
  });

  test(`get_candidate_report у SA без причины → 400 reason_required, с неверной причиной → 400 invalid_reason @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const { api, candidateId } = await openTrail(admin, FLAGGED[0]);
    // Источник: решение D-25 и DB-тест M4 (ответ 05.11) — SA получает отчёт только с допустимой причиной; здесь допустимой причины НЕ шлём.
    const none = await api.rpc('get_candidate_report', { p_candidate_id: candidateId });
    expect(none.status(), await none.text()).toBe(400);
    expect(await none.text()).toContain('reason_required');
    const bad = await api.rpc('get_candidate_report', { p_candidate_id: candidateId, p_reason: 'qa-not-a-reason' });
    expect(bad.status(), await bad.text()).toBe(400);
    expect(await bad.text()).toContain('invalid_reason');
  });

  test(`диалог «צפייה בתוכן» без причины: «יש לבחור את סיבת הגישה לתוכן», контент не открывается @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    await openSupport(admin);
    await openRowMenu(admin, FLAGGED[1]);
    await admin.getByRole('menuitem', { name: 'צפייה בתוכן', exact: true }).click();
    const dialog = admin.getByRole('dialog');
    await expect(dialog.getByText(`לפתוח את התוכן של ${FLAGGED[1]}?`)).toBeVisible();
    await expect(dialog.getByLabel('סיבת הגישה')).toHaveValue('');

    // Источник: ACL-004 / D-25 — без выбора причины контент не открывается.
    await dialog.getByRole('button', { name: 'צפייה בתוכן', exact: true }).click();
    await expect(dialog.getByText('יש לבחור את סיבת הגישה לתוכן')).toBeVisible();
    await expect(admin).toHaveURL(/\/admin\/support(\?|$)/);
    await expect(admin).not.toHaveURL(/reason=/);
    await dialog.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(dialog).toBeHidden();
  });
});
